from math import comb, gcd

def check_n(n):
    if gcd(n, 6) != 1:
        return False

    a_start = (n // 3) + 1
    a_end = n // 2

    for a in range(a_start, a_end + 1):
        k = n - 2*a
        if k == 0:
            continue
        if comb(a-1, k-1) % k != 0:
            return False

    return True

count = 0
results = []
for n in range(2, 200):
    if check_n(n):
        count += 1
        results.append(n)

print(f"Count: {count}")
print(f"n values: {results}")
